window.TADABBUR_ABASA = {"_meta":{"description":"تدبّر سورة عبس (٨٠)، وسورةٌ مكّيّةٌ. محورُها معاتبةُ الله لنبيّه ﷺ حين عبس وأعرض عن الأعمى (عبدِ الله بنِ أمِّ مكتوم) الذي جاء يسأل عن الحقّ، وانشغل بدعوةِ صناديدِ قريش؛ وتقريرُ أنّ القرآنَ تذكرةٌ في صحفٍ مكرّمةٍ بأيدي الملائكة، ثم توبيخُ الإنسانِ الكفورِ وتذكيرُه بأصلِ خلقه من نطفةٍ وتيسيرِ سبيله ثم إماتتِه وبعثِه، والاستدلالُ بنعمِ الطعامِ والنبات، وختامُها بمشهدِ الصاخّةِ (القيامة) يومَ يفرّ المرءُ من أقرب الناسِ إليه، وانقسامِ الوجوهِ بين مسفرةٍ مستبشرةٍ وعليها غبرةٌ ترهقها قترة. فيها «عبس وتولى أن جاءه الأعمى»، و«كلا إنها تذكرة»، و«فإذا جاءت الصاخة يوم يفر المرء من أخيه».","honesty":"كلُّ وقفةٍ مُسنَدةٌ إلى تفسيرٍ معتمد (ابن كثير/السعدي) وموسومةٌ بدرجتها. حالُ القلبِ والعملُ اجتهاديٌّ موسوم. لا يُقدَّم شيءٌ على أنه إعجازٌ مثبت."},"n":80,"name":"عبس","total_ayahs":42,"audio":["audio/080001.mp3","audio/080002.mp3","audio/080003.mp3","audio/080004.mp3","audio/080005.mp3","audio/080006.mp3","audio/080007.mp3","audio/080008.mp3","audio/080009.mp3","audio/080010.mp3"],"passages":[{"title":"معاتبةُ الإعراضِ عن الأعمى وأنّ القرآنَ تذكرة","range":[1,16],"theme":"معاتبةُ النبيِّ على عبوسه وإعراضه عن الأعمى الطالبِ للحقّ «عبس وتولى أن جاءه الأعمى وما يدريك لعله يزكى... وأما من جاءك يسعى وهو يخشى فأنت عنه تلهى»، وأنّ القرآنَ تذكرة «كلا إنها تذكرة فمن شاء ذكره في صحف مكرمة مرفوعة مطهرة بأيدي سفرة كرام بررة»","verses":[{"n":1,"reflection":{"text":"«عبس وتولى»: قطّب النبيُّ ﷺ وجهه وأعرض (حين جاءه الأعمى يسأل وهو منشغلٌ بدعوةِ الكبراء)؛ ففي هذا بيانُ معاتبةِ الله لنبيّه على العبوسِ والإعراض عن طالبِ الحقّ؛ فلا تعبس في وجهِ طالبِ الحقِّ ولا تُعرِض عنه، فطالبُ الخيرِ أحقُّ بالإقبال، فأقبل عليه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإقبالُ على طالبِ الحقِّ وعدمُ الإعراضِ عنه."},"action":{"text":"تأمّل المعاتبةَ: عبس، أي قطّب النبيُّ ﷺ وجهه وكلح، وتولى، أي أعرض بوجهه؛ وذلك حين جاءه عبدُ الله بنُ أمِّ مكتومٍ الأعمى يسأله عن الحقِّ ويستقرئه، والنبيُّ ﷺ منشغلٌ بدعوةِ صناديدِ قريشٍ يرجو إسلامهم، فشقّ عليه قطعُ كلامه، فعبس وأعرض، فعاتبه الله «عبس وتولى»؛ ففي هذا بيانُ معاتبةِ الله لنبيّه ﷺ على عبوسِه وإعراضِه عن الأعمى الطالبِ للحقّ، انشغالًا بدعوةِ الكبراء؛ وفيه رفعُ قدرِ فقراءِ المؤمنين طالبي الحقّ؛ فطالبُ الحقِّ أحقُّ بالإقبالِ من المُعرِض؛ فلا تعبس أنت في وجهِ طالبِ الحقِّ والعلمِ والخير، ولا تُعرِض عنه، ولو كان فقيرًا أو ضعيفًا، بل أقبل عليه وبشّه؛ واصبر نفسك مع الذين يدعون ربّهم بالغداةِ والعشيّ يريدون وجهه ولا تعدُ عيناك عنهم؛ ولا تطرد الذين يدعون ربّهم؛ فطالبُ الحقِّ أحقُّ بالإقبال، والإعراضُ عنه لا يليق؛ فأقبل عليه، وبشّه، ولا تعبس؛ فمن أقبل على طالبِ الحقِّ أحسن، ومن أعرض عنه أخطأ؛ فاجعل الإقبالَ على طالبِ الحقِّ دأبك."},"sabab":{"text":"معاتبةُ النبيِّ ﷺ لمّا عبس في وجهِ ابنِ أمِّ مكتومٍ الأعمى وأعرض عنه، انشغالًا بدعوةِ صناديدِ قريش (سببُ نزولٍ صحيح).","source":"صحيح البخاري/الترمذي (سبب نزول)","grade":"ma'thur"},"qadiyya":{"title":"قضيّةُ عتابٍ على نيّةٍ صالحة","question":"جاء رجلٌ أعمى من المؤمنين يسأل النبيَّ ﷺ ويتعلّم منه، **وعنده رجلٌ من الأغنياء.**\n**فأقبل ﷺ على الغنيّ رجاءَ أن يهتديَ، وأعرض عن الأعمى.**\n**فنزل**: «**عبس وتولّى، أن جاءه الأعمى**».\n**والذي يستوقف أنّ الباعث كان صالحًا**: **الحرصُ على هداية الخلق.**\nفالقضيّة: **لماذا وقع العتابُ مع صلاح الباعث؟** ثمّ: **ما وجهُ تقديم الأعمى على الغنيّ؟** ثمّ: **ما الذي يُتعلّم من طريقة العتاب نفسِها؟**","background":"ولا يُفهم موضعُ العتاب حتى نفرّق بين أمرين:\n**النيّةُ**: **ولمن كانت هذه النيّة صالحةً محمودة.**\n**والترتيبُ**: **أيُّهما يُقدَّم عند التزاحم.**\n**وصلاحُ النيّة لا يُصحّح خطأ الترتيب.**\n**فقد يكون الرجلُ صادقًا في قصده، ثمّ يُخطئ في تقدير الأولى؛ فيُنفق جهدَه في غير موضعه.**\n**وهذا هو موضعُ العتاب في الآية، لا في القصد.**","what_happened":"**ذكر السعديُّ سبب النزول ووصف الحال وصفًا يُبيّن الباعث**: «**أنّه جاء رجلٌ من المؤمنين أعمى يسأل النبيَّ صلّى الله عليه ويتعلّم منه، وجاءه رجلٌ من الأغنياء**».\n**⭐ ثمّ نصّ على حسن الباعث صراحةً**: «**وكان صلّى الله عليه وسلّم حريصًا على هداية الخلق، فمال صلّى الله عليه وسلّم**... **إلى الغنيّ، وصدّ عن الأعمى الفقير، رجاءَ لهداية ذلك الغنيّ، وطمعًا في تزكيته**».\n**⭐ ثمّ وصف العتاب بوصفٍ لافت**: «**فعاتبه اللهُ بهذا العتاب اللطيف**».\n**ثمّ فسّر اللفظين**: ﴿عبس﴾ «**في وجهه**»، ﴿وتولّى﴾ «**في بدنه**».\n**⭐ ثمّ ذكر الفائدة التي فاتت بالإعراض**: «**ثمّ ذكر الفائدة في الإقبال عليه**»، **وفسّرها: «أي: يتطهّر عن الأخلاق الرذيلة، ويتّصف بالأخلاق الجميلة**».\n**ثمّ الثانية**: ﴿أو يذّكّر فتنفعه الذكرى﴾ «**أي: يتذكّر ما ينفعه فيعمل بتلك الذكرى**».","the_verdict":"**فالحاصلُ أنّ العتاب لم يقع على قصدٍ فاسد، بل على تقديمٍ في غير موضعه.**\n**⭐ وهذا أنفعُ ما في السورة، لأنّه يكشف خطأً لا يُحسّ به صاحبُه.**\n**فإنّ من كان قصدُه صالحًا يطمئنّ إلى قصده، فلا يُراجع اختياره.**\n**والآيةُ تُبيّن أنّ الاختيار يُراجَع وإن صحّ القصد.**\n**⭐ وأمّا وجهُ تقديم الأعمى فقد أشار إليه بموضع ﴿وما يُدريك﴾.**\n**فالمقبِلُ عليك طالبًا قد أتاك بنفسه، وأمرُه بيدك؛ والمعرِضُ عنك لا تملك أمرَه.**\n**فالذي جاء يسأل حاضرٌ مستعدّ، والذي يُرجى إسلامُه احتمالٌ.**\n**فقُدّم المتحقّقُ على المرجوّ.**\n**⭐ ثمّ إنّ الأعمى جاء لينتفع هو، والغنيَّ أُريد لينتفع به الدين.**\n**فالأوّلُ مقصودٌ لذاته، والثاني مقصودٌ لغيره.**\n**ومن قدّم من يُنتفع به على من يُنتفع، فقد جعل الناس وسائل.**\n**⭐ وأمّا وصفُ الإمام للعتاب بأنّه «لطيف» فينبغي أن يُتأمّل في نظم السورة.**\n**فقد جاء أوّلُها بصيغة الغائب: ﴿عبس وتولّى﴾، ولم يُقل: عبستَ وتولّيت.**\n**ثمّ انتقل إلى الخطاب: ﴿وما يُدريك﴾.**\n**فبُدئ بما لا مواجهة فيه، ثمّ خُوطب.**\n**وهذا أدبٌ في العتاب يُتعلّم: أن يُذكر الفعلُ أوّلًا من غير تعيين، ثمّ يُوجَّه الكلام.**\n**⭐ ولاحظ أنّ العتاب ذُكر ﴿عبس﴾ في الوجه و﴿تولّى﴾ في البدن، كما فسّره الإمام.**\n**فالإعراضُ وقع في أدنى ما يقع فيه: تغيّرُ وجهٍ وانصرافُ بدن، لا طردٌ ولا كلامٌ سيّئ.**\n**ومع ذلك عوتب عليه.**\n**فما بالُ من يصنع أكثر من ذلك بمن جاءه محتاجًا؟**","for_you":"**فأمّا الذي تخرج به فثلاثة:**\n**الأوّل: راجع ترتيبك لا نيّتك فقط.** **فإذا وجدتَ نفسك تعتذر بأنّ قصدك حسن، فاسأل: أهذا هو الأولى بوقتي الآن؟** **فقد كان قصدُه ﷺ الهداية، وعوتب على الترتيب.**\n**والثاني: قدّم الطالب على المطلوب.** **فمن جاءك يسأل حقُّه أن يُقدَّم على من تسعى إليه.** **وهذا يقع كثيرًا لمن يُعلّم أو يُدير أو يخدم الناس: ينشغل بمن يُريد كسبَه عمّن جاءه بالفعل.**\n**والثالث: انتبه إلى الإعراض الصغير.** **فالمعاتَبُ عليه في السورة تغيّرُ وجهٍ وانصرافُ بدن.** **فانظر: كيف يكون وجهك حين يأتيك من لا ترجو منه شيئًا؟** **فإنّ الوجه يُترجم ما في القلب قبل اللسان.**","grade":"ma'thur","source":"ذكرُ السعديّ للسبب («أنه جاء رجل من المؤمنين أعمى يسأل النبي صلى الله عليه ويتعلم منه»، «وجاءه رجل من الأغنياء»)، وتنصيصُه على الباعث («وكان صلى الله عليه وسلم حريصا على هداية الخلق»، «إلى الغني، وصد عن الأعمى الفقير، رجاء لهداية ذلك الغني، وطمعا في تزكيته»)، ووصفُه للعتاب («فعاتبه الله بهذا العتاب اللطيف»)، وتفسيرُه للفظين («في وجهه»، «في بدنه»)، وذكرُه للفائدة («ثم ذكر الفائدة في الإقبال عليه»، «أي: يتطهر عن الأخلاق الرذيلة، ويتصف بالأخلاق الجميلة»، «أي: يتذكر ما ينفعه، فيعمل بتلك الذكرى»): كلُّها بنصّها في تفسير السعديّ (٨٠:١ و٨٠:٢ و٨٠:٣ و٨٠:٤).","honesty":"وممّا يجب أن يُقال:\n**تفريقُنا في التمهيد بين النيّة والترتيب، تحريرٌ منّا لموضع العتاب؛ وليس نصًّا للسعديّ، وإن كان مبنيًّا على تنصيصه على حسن الباعث ووقوع العتاب معه.**\n**وأمّا تعليلُنا لتقديم الأعمى (أنّه متحقّقٌ والآخرُ مرجوّ، وأنّ الأوّل مقصودٌ لذاته) فاستنباطٌ منّا؛ ولم يذكره السعديُّ في القدر الذي نقلناه، ومن رأى أنّا وسّعنا فليردّه.**\n**وأمّا ملاحظتُنا على الانتقال من الغيبة إلى الخطاب، فملاحظةٌ منّا على نظم السورة، بنيناها على وصفه العتابَ باللطف.**\n**وسببُ النزول نقلناه كما ساقه السعديُّ، ولم نتتبّع رواياتِه ولا ألفاظَها؛ ومظانُّها كتبُ التفسير المسندة.**"}},{"n":2,"reflection":{"text":"«أن جاءه الأعمى»: لأجلِ أن جاءه الأعمى (عبدُ الله بنُ أمِّ مكتوم) يسأل عن الحقّ؛ ففي هذا بيانُ أنّ سببَ العتابِ إعراضُه عمّن جاء يطلب الهدى؛ فلا تحتقر ضعيفًا طالبًا للحقّ، فطالبُ الهدى وإن كان ضعيفًا كريمٌ عند الله، فأكرمه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إكرامُ طالبِ الهدى وإن كان ضعيفًا، وعدمُ احتقاره."},"action":{"text":"تأمّل سببَ العتاب: أن جاءه الأعمى، أي عاتبه الله لأجلِ أن جاءه الأعمى (عبدُ الله بنُ أمِّ مكتوم) يسأله ويستهديه ويطلب منه أن يعلّمه ممّا علّمه الله، فأعرض عنه النبيُّ ﷺ لانشغاله بغيره «أن جاءه الأعمى»؛ ففي هذا بيانُ أنّ سببَ عتابِ الله لنبيّه إعراضُه عن هذا الأعمى الفقيرِ الذي جاء طالبًا للحقّ والهدى؛ وفيه رفعُ قدرِ طالبِ الهدى وإن كان ضعيفًا فقيرًا أعمى؛ فطالبُ الهدى كريمٌ عند الله وإن كان ضعيفًا؛ فلا تحتقر أنت ضعيفًا أو فقيرًا أو أعمى إذا جاء طالبًا للحقّ والعلمِ والهدى، بل أكرمه وأقبل عليه، فإنّ الله رفع قدره؛ ولا تطرد الذين يدعون ربّهم بالغداةِ والعشيّ؛ إنّ أكرمكم عند الله أتقاكم؛ ربّ أشعثَ أغبرَ ذي طمرين لو أقسم على الله لأبرّه؛ فطالبُ الهدى كريمٌ وإن ضعف، واحتقارُه لا يليق؛ فأكرمه، وأقبل عليه؛ فمن أكرم طالبَ الهدى أحسن، ومن احتقره أخطأ؛ فاجعل إكرامَ طالبِ الهدى دأبك."}},{"n":3,"reflection":{"text":"«وما يدريك لعله يزكى»، وأيُّ شيءٍ يُعلِمك، يا محمد، لعلّ هذا الأعمى يتطهّر بما يتعلّمه منك؟ ففي هذا بيانُ أنّ طالبَ الحقِّ قد يكون أزكى ممّن أقبلت عليه؛ فلا تزدرِ طالبَ الحقّ، فلعلّه أزكى من غيره، فأقبل عليه راجيًا زكاته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"رجاءُ زكاةِ طالبِ الحقِّ وعدمُ ازدرائه."},"action":{"text":"تأمّل رجاءَ الزكاة: وما يدريك، يا محمد، أي أيُّ شيءٍ يُعلِمك، لعله يزّكى، أي لعلّ هذا الأعمى يتطهّر ويتزكّى بما يتعلّمه منك من الخيرِ والهدى، فينمو على الإيمانِ والطاعة؛ فلا تدري لعلّه أزكى ممّن أقبلت عليه من الكبراء «وما يدريك لعله يزكى»؛ ففي هذا بيانُ أنّ طالبَ الحقِّ (الأعمى) قد يكون أزكى وأنفعَ من الكبراءِ الذين أقبل عليهم النبيُّ ﷺ، وأنّ الإقبالَ عليه أولى لرجاءِ زكاته؛ فطالبُ الحقِّ قد يكون أزكى من غيره؛ فلا تزدرِ أنت طالبَ الحقِّ والخير، فلعلّه أزكى وأتقى من غيره، وأقبل عليه راجيًا أن يتزكّى بما يتعلّم؛ قد أفلح من تزكّى؛ فلعلّه يزّكى؛ وأمّا من جاءك يسعى وهو يخشى؛ فطالبُ الحقِّ قد يكون أزكى، والإقبالُ عليه أولى؛ فأقبل عليه، ولا تزدره، وارجُ زكاته؛ فمن أقبل على طالبِ الحقِّ أصاب، ومن ازدراه أخطأ؛ فاجعل رجاءَ زكاةِ طالبِ الحقِّ دأبك."}},{"n":4,"reflection":{"text":"«أو يذكر فتنفعه الذكرى»: أو يتّعظ بما يسمع منك فتنفعه الموعظة؛ ففي هذا بيانُ أنّ طالبَ الحقِّ يُرجى انتفاعه بالذكرى؛ فأقبل على من يُرجى انتفاعه بالذكرى، فالذكرى تنفع من أقبل عليها، فذكّر من طلبها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تذكيرُ من يُرجى انتفاعه بالذكرى والإقبالُ عليه."},"action":{"text":"تأمّل رجاءَ الانتفاع: أو يذّكر، أي أو يتّعظ ويتذكّر هذا الأعمى بما يسمع منك من الوحيِ والموعظة، فتنفعه الذكرى، أي فتنفعه تلك الموعظةُ والتذكيرُ في دينه ودنياه وآخرته؛ فهو مُقبِلٌ يُرجى انتفاعه «أو يذكر فتنفعه الذكرى»؛ ففي هذا بيانُ أنّ هذا الأعمى الطالبَ للحقِّ يُرجى أن يتّعظ فتنفعه الذكرى، بخلافِ الكبراءِ المستغنين المعرضين؛ فأولى بالإقبالِ من يُرجى انتفاعه؛ فأقبل أنت على من يُرجى انتفاعه بالذكرى والموعظة، وذكّره، فإنّ الذكرى تنفع من أقبل عليها بقلبه؛ وذكّر فإنّ الذكرى تنفع المؤمنين؛ فذكّر إن نفعت الذكرى سيذّكّر من يخشى؛ إنما تنذر من اتّبع الذكر؛ فالذكرى تنفع المُقبِلَ عليها، والإقبالُ على من يُرجى انتفاعه أولى؛ فذكّر من طلبها، وأقبل عليه؛ فمن ذكّر المُقبِلَ نفعه، ومن أعرض عنه حرمه؛ فاجعل تذكيرَ من يُرجى انتفاعه دأبك."}},{"n":5,"reflection":{"text":"«أما من استغنى»: أما من استغنى (بمالِه وجاهه) عن الإيمانِ والهدى؛ ففي هذا بيانُ ذمِّ الاستغناءِ عن الهدى بالدنيا؛ فاحذر أن يُلهِيك الاستغناءُ عن طلبِ الهدى، فالاستغناءُ عن الهدى سببُ الإعراض، فافتقر إلى ربّك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الافتقارُ إلى الله وطلبِ الهدى، والحذرُ من الاستغناءِ بالدنيا."},"action":{"text":"تأمّل ذمَّ المستغني: أما من استغنى، أي من استغنى بمالِه وجاهه وسلطانه عن الإيمانِ والهدى، فرأى نفسه غنيًّا لا يحتاج إلى ما عندك من الحقّ، فأعرض واستكبر «أما من استغنى»؛ ففي هذا بيانُ ذمِّ من استغنى بالدنيا (المالِ والجاه) عن الإيمانِ والهدى، وأنّ استغناءه سببُ إعراضه واستكباره، وهم صناديدُ قريش؛ فالاستغناءُ عن الهدى بالدنيا سببُ الإعراضِ والكبر؛ فاحذر أنت أن يُلهِيك الاستغناءُ بالمالِ والجاه عن طلبِ الهدى والافتقارِ إلى الله، بل افتقر إلى ربّك وإلى هداه دائمًا؛ كلّا إنّ الإنسانَ ليطغى أن رآه استغنى؛ يا أيها الناسُ أنتم الفقراءُ إلى الله والله هو الغنيُّ الحميد؛ أيحسب أن لن يقدر عليه أحد؛ فالاستغناءُ عن الهدى سببُ الإعراض، والافتقارُ إلى الله سبيلُ الهدى؛ فافتقر إليه، واطلب الهدى، ولا تستغنِ؛ فمن افتقر إلى الله اهتدى، ومن استغنى بالدنيا أعرض؛ فاجعل الافتقارَ إلى الله والحذرَ من الاستغناءِ دأبك."}},{"n":6,"reflection":{"text":"«فأنت له تصدى»: فأنت، يا محمد، تُقبِل عليه وتتعرّض له وتهتمّ بأمره (طمعًا في إسلامه)؛ ففي هذا بيانُ أنّ الإقبالَ على المستغني المعرضِ ليس أولى؛ فلا تجعل إقبالك على المستغني المعرضِ أكثرَ من إقبالك على طالبِ الحقّ، فالإقبالُ يكون بحسبِ النفع، فوازن.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"موازنةُ الإقبالِ بحسبِ نفعِ المدعوّ لا بجاهه."},"action":{"text":"تأمّل الإقبالَ على المستغني: فأنت له، أي للمستغني المعرض، تصدّى، أي تُقبِل عليه وتتعرّض له وتتصدّى لدعوته وتهتمّ بأمره وتُصغي إليه، طمعًا في إسلامه لِما تظنّ في إسلامه من نصرةِ الدين «فأنت له تصدى»؛ ففي هذا بيانُ عتابِ الله لنبيّه على شدّةِ إقباله على المستغني المعرضِ (الكبراء)، مع أنّ إقباله على طالبِ الحقّ أولى؛ فالإقبالُ ينبغي أن يكون بحسبِ نفعِ المدعوِّ وإقبالِه لا بحسبِ جاهه؛ فلا تجعل أنت إقبالك على المستغني المعرضِ أكثرَ من إقبالك على طالبِ الحقِّ المُقبِل، بل وازن إقبالك بحسبِ النفعِ والإقبالِ لا الجاهِ والمال؛ ولا تعدُ عيناك عنهم تريد زينةَ الحياةِ الدنيا؛ ولا تطرد الذين يدعون ربّهم؛ واخفض جناحك للمؤمنين؛ فالإقبالُ يكون بحسبِ النفعِ لا الجاه، والموازنةُ واجبة؛ فوازن إقبالك، وأقبل على المُقبِل؛ فمن وازن أصاب، ومن أقبل على الجاهِ دون النفعِ أخطأ؛ فاجعل موازنةَ الإقبالِ بحسبِ النفعِ دأبك."}},{"n":7,"reflection":{"text":"«وما عليك ألا يزكى»، وما عليك، يا محمد، من تبعةٍ إن لم يتزكّ هذا المستغني (فما عليك إلا البلاغ)؛ ففي هذا بيانُ أنّ الهدايةَ ليست إلى الداعية، وأنه ليس مسؤولًا عن عدمِ تزكّي المُعرِض؛ فبلّغ الحقَّ ولا تحمل همَّ عدمِ اهتداءِ المعرضين، فالهدايةُ بيدِ الله، فبلّغ وكِل الأمرَ إليه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التبليغُ وعدمُ حملِ همِّ عدمِ اهتداءِ المعرضين، وتفويضُ الهدايةِ لله."},"action":{"text":"تأمّل رفعَ التبعة: وما عليك، يا محمد، ألا يزّكى، أي ليس عليك تبعةٌ ولا لومٌ إن لم يتطهّر هذا المستغني ولم يؤمن، فما أنت إلا مبلّغٌ منذر، والهدايةُ بيدِ الله؛ فلا تشغل نفسك بالحرصِ على من أعرض «وما عليك ألا يزكى»؛ ففي هذا بيانُ أنّ الهدايةَ ليست إلى النبيِّ ﷺ ولا إلى الداعية، وأنه ليس مسؤولًا عن عدمِ تزكّي المُعرِض، فما عليه إلا البلاغ؛ فالداعيةُ مبلّغٌ لا مسؤولٌ عن الهداية؛ فبلّغ أنت الحقَّ ولا تحمل همَّ عدمِ اهتداءِ المعرضين، ولا تُهلِك نفسك حسرةً عليهم، فالهدايةُ بيدِ الله وحده؛ فلعلّك باخعٌ نفسك على آثارهم إن لم يؤمنوا بهذا الحديثِ أسفًا؛ إنك لا تهدي من أحببتَ ولكنّ الله يهدي من يشاء؛ فما أرسلناك عليهم حفيظًا إن عليك إلا البلاغ؛ فالتبليغُ وظيفتك، والهدايةُ بيدِ الله؛ فبلّغ، ولا تحمل الهمَّ، وفوّض الهدايةَ إليه؛ فمن بلّغ وفوّض ارتاح، ومن حمل همَّ الهدايةِ أتعب نفسه؛ فاجعل التبليغَ وتفويضَ الهدايةِ لله دأبك."}},{"n":8,"reflection":{"text":"«وأما من جاءك يسعى»، وأما من جاءك، يا محمد، يسعى ويجدّ في طلبِ الحقّ (الأعمى)؛ ففي هذا بيانُ فضلِ من سعى في طلبِ الحقّ؛ فأقبل على من سعى في طلبِ الحقّ، فالساعي في طلبِ الحقِّ أحقُّ بالإكرام، فأكرم الساعين إليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إكرامُ الساعي في طلبِ الحقّ والإقبالُ عليه."},"action":{"text":"تأمّل فضلَ الساعي: وأما من جاءك، يا محمد، يسعى، أي يجدّ ويسرع في المجيءِ إليك طالبًا للحقِّ والهدى والعلم، حريصًا على الخير، وهو الأعمى «وأما من جاءك يسعى»؛ ففي هذا بيانُ فضلِ من سعى وجدّ في طلبِ الحقِّ والهدى، وأنه أحقُّ بالإقبالِ والإكرام من المُعرِض المستغني؛ فالساعي في طلبِ الحقِّ أحقُّ بالإكرامِ والإقبال؛ فأقبل أنت على من سعى في طلبِ الحقِّ والعلمِ والخير، وأكرمه، ولا تُؤثِر عليه المُعرِضين وإن كانوا كبراء؛ ومن أراد الآخرةَ وسعى لها سعيها وهو مؤمنٌ فأولئك كان سعيهم مشكورًا؛ واصبر نفسك مع الذين يدعون ربّهم؛ إنّ هذا القرآنَ يهدي للتي هي أقوم؛ فالساعي في طلبِ الحقِّ كريمٌ أحقُّ بالإقبال؛ فأقبل عليه، وأكرمه؛ فمن أكرم الساعيَ للحقِّ أصاب، ومن أعرض عنه أخطأ؛ فاجعل إكرامَ الساعي في طلبِ الحقِّ دأبك."}},{"n":9,"reflection":{"text":"«وهو يخشى»، وهو مع سعيه يخشى الله ويخاف عقابه (فجمع بين السعيِ والخشية)؛ ففي هذا بيانُ فضلِ من جمع بين طلبِ الحقِّ والخشية؛ فأقبل على أهلِ الخشيةِ الطالبين للحقّ، فالخشيةُ مع السعيِ أكملُ الحال، فاطلبها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين طلبِ الحقِّ وخشيةِ الله، وإكرامُ أهلِ الخشية."},"action":{"text":"تأمّل خشيةَ الساعي: وهو يخشى، أي وهذا الساعي في طلبِ الحقِّ يخشى الله ويخاف عقابه، فجمع بين السعيِ في طلبِ الحقِّ وخشيةِ الله؛ فهو أهلٌ للإقبالِ لجمعه بين الحرصِ والخشية «وهو يخشى»؛ ففي هذا بيانُ فضلِ من جمع بين السعيِ في طلبِ الحقِّ وخشيةِ الله، وأنّ ذلك أكملُ الحالِ وأحقُّ بالإقبالِ والإكرام؛ فالخشيةُ مع السعيِ في طلبِ الحقِّ أكملُ الأحوال؛ فاجمع أنت بين السعيِ في طلبِ الحقِّ والعلمِ وخشيةِ الله، وأقبل على أهلِ الخشيةِ الطالبين للحقّ وأكرمهم؛ إنما يخشى الله من عباده العلماء؛ الذين يخشون ربّهم بالغيب؛ ومن يطعِ الله ورسولَه ويخش الله ويتّقه فأولئك هم الفائزون؛ فالخشيةُ مع طلبِ الحقِّ أكملُ الحال، وأهلها أحقُّ بالإكرام؛ فاجمع بينهما، وأكرم أهلهما؛ فمن جمع بين طلبِ الحقِّ والخشيةِ كمُل، ومن فرّط نقص؛ فاجعل الجمعَ بين طلبِ الحقِّ وخشيةِ الله دأبك."}},{"n":10,"reflection":{"text":"«فأنت عنه تلهى»: فأنت، يا محمد، تتشاغل عنه وتُعرِض (منشغلًا بغيره)؛ ففي هذا تمامُ العتاب: الإعراضُ عن الساعي الخاشي؛ فلا تتشاغل عمّن سعى إليك خاشيًا طالبًا للحقّ، فالإعراضُ عن الخاشي الطالبِ لا يليق، فأقبل عليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإقبالُ على الخاشي الطالبِ للحقّ وعدمُ التشاغلِ عنه."},"action":{"text":"تأمّل تمامَ العتاب: فأنت، يا محمد، عنه، أي عن هذا الساعي الخاشي الطالبِ للحقّ، تلهّى، أي تتشاغل وتتغافل وتُعرِض، منشغلًا بغيره من الكبراء؛ فعُوتِب على ذلك «فأنت عنه تلهى»؛ ففي هذا بيانُ تمامِ عتابِ الله لنبيّه: أنه تشاغل وأعرض عن هذا الساعي الخاشي الطالبِ للحقّ، انشغالًا بالمستغنين المعرضين؛ فالإعراضُ عن الخاشي الطالبِ للحقِّ لا يليق؛ فلا تتشاغل أنت عمّن سعى إليك خاشيًا طالبًا للحقّ والعلمِ والخير، ولا تُعرِض عنه، بل أقبل عليه واهتمّ بأمره؛ واصبر نفسك مع الذين يدعون ربّهم بالغداةِ والعشيّ يريدون وجهه؛ ولا تطرد الذين يدعون ربّهم؛ فأقبل على المُقبِل الخاشي؛ فالإعراضُ عن الخاشي الطالبِ لا يليق، والإقبالُ عليه أولى؛ فأقبل عليه، ولا تتشاغل عنه؛ فمن أقبل على الخاشي الطالبِ أحسن، ومن أعرض عنه أخطأ؛ فاجعل الإقبالَ على الخاشي الطالبِ للحقِّ دأبك."}},{"n":11,"reflection":{"text":"«كلا إنها تذكرة»: حقًّا، إنّ هذه السورةَ (أو آياتِ القرآن) تذكرةٌ وعظة؛ ففي هذا بيانُ أنّ القرآنَ تذكرةٌ، وردعٌ عن الإعراضِ عن طالبه؛ فاتّعظ بالقرآنِ فإنه تذكرة، ولا تُعرِض عمّن يطلبه، فالقرآنُ تذكرةٌ فأقبل عليه، فتذكّر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاتّعاظُ بالقرآنِ واتّخاذُه تذكرة."},"action":{"text":"تأمّل كونَ القرآنِ تذكرة: كلّا، أي حقًّا، وردعًا عن معاودةِ الإعراضِ عن طالبِ الحقّ، إنها، أي هذه السورةَ أو آياتِ القرآن، تذكرةٌ، أي عظةٌ وتذكيرٌ يتذكّر بها من أراد الخير، فينبغي أن يُقبَل عليها ويُقبَل على طالبها «كلا إنها تذكرة»؛ ففي هذا بيانُ أنّ القرآنَ تذكرةٌ وموعظة، وردعٌ عن الإعراضِ عمّن يطلبها، فمن جاء طالبًا للتذكرةِ فهو أحقُّ بالإقبال؛ فالقرآنُ تذكرةٌ يُقبَل عليها ويُقبَل على طالبها؛ فاتّعظ أنت بالقرآنِ واتّخذه تذكرةً وموعظة، وتدبّره، ولا تُعرِض عمّن يطلبه ويتّعظ به؛ فذكّر إنما أنت مذكّر؛ وذكّر فإنّ الذكرى تنفع المؤمنين؛ إنّ هذه تذكرةٌ فمن شاء اتّخذ إلى ربّه سبيلًا؛ فالقرآنُ تذكرة، والاتّعاظُ به والإقبالُ على طالبه أولى؛ فاتّعظ به، وأقبل على طالبه؛ فمن اتّعظ بالقرآنِ اهتدى، ومن أعرض عنه ضلّ؛ فاجعل الاتّعاظَ بالقرآنِ واتّخاذَه تذكرةً دأبك."}},{"n":12,"reflection":{"text":"«فمن شاء ذكره»: فمن شاء ذكر القرآنَ واتّعظ به وانتفع؛ ففي هذا بيانُ أنّ التذكّرَ باختيارِ العبد؛ فبادر بذكرِ القرآنِ والاتّعاظِ به، فبابُ التذكّرِ مفتوحٌ لمن شاء، فبادر إليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بذكرِ القرآنِ والاتّعاظِ به."},"action":{"text":"تأمّل بابَ التذكّر: فمن شاء، من الناسِ، ذكره، أي ذكر القرآنَ واتّعظ به وحفظه وعمل بمقتضاه وانتفع بمواعظه؛ فالبابُ مفتوحٌ والاختيارُ للعبدِ في أن يتذكّر أو يُعرِض، ومشيئتُه مندرجةٌ تحت مشيئةِ الله «فمن شاء ذكره»؛ ففي هذا بيانُ أنّ التذكّرَ بالقرآنِ والانتفاعَ به متعلّقٌ بمشيئةِ العبدِ ورغبته، فمن أراد الخيرَ ذكره واتّعظ به؛ فبابُ التذكّرِ مفتوحٌ لمن شاء أن يسلكه؛ فبادر أنت بذكرِ القرآنِ والاتّعاظِ به والعملِ بمقتضاه، ولا تحرم نفسك وقد فُتِح لك البابُ، واغتنم إرادتك للخير؛ إنّ هذه تذكرةٌ فمن شاء اتّخذ إلى ربّه سبيلًا؛ فمن شاء منكم أن يتقدّم أو يتأخّر؛ كلّا إنه تذكرة فمن شاء ذكره؛ فالتذكّرُ باختيارِ العبد، والموفّقُ من بادر إليه؛ فبادر بذكرِ القرآنِ والاتّعاظِ به؛ فمن ذكره واتّعظ اهتدى، ومن أعرض ضلّ؛ فاجعل المبادرةَ بذكرِ القرآنِ دأبك."}},{"n":13,"reflection":{"text":"«في صحف مكرمة»: القرآنُ مثبتٌ في صحفٍ معظّمةٍ مكرّمةٍ عند الله (اللوحِ المحفوظ)؛ ففي هذا بيانُ تكريمِ الله للقرآنِ في صحفه؛ فعظّم القرآنَ الذي عظّمه الله في صحفه المكرّمة، فالقرآنُ مكرّمٌ عند الله، فأكرمه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ القرآنِ الذي كرّمه الله في صحفه."},"action":{"text":"تأمّل تكريمَ الصحف: في صحفٍ مكرّمةٍ، أي إنّ هذه التذكرةَ (القرآنَ) مثبتةٌ في صحفٍ معظّمةٍ مكرّمةٍ عند الله، مكرّمةٍ لكرامةِ ما فيها من كلامِ الله وهداه، وهي في اللوحِ المحفوظ، أو الصحفِ التي بأيدي الملائكة «في صحف مكرمة»؛ ففي هذا بيانُ تكريمِ الله للقرآنِ وتعظيمِه، إذ أثبته في صحفٍ مكرّمةٍ معظّمةٍ عنده؛ فالقرآنُ مكرّمٌ معظّمٌ عند الله في صحفه؛ فعظّم أنت القرآنَ وأكرمه في قلبك وعملك، كما عظّمه الله وكرّمه في صحفه المكرّمة، فلا تستهن به ولا تهجره؛ إنه لقرآنٌ كريم في كتابٍ مكنون؛ بل هو قرآنٌ مجيد في لوحٍ محفوظ؛ كلّا إنها تذكرةٌ فمن شاء ذكره في صحفٍ مكرّمة؛ فالقرآنُ مكرّمٌ عند الله، وتعظيمُه واجب؛ فعظّمه، وأكرمه، ولا تهجره؛ فمن عظّم القرآنَ أكرمه الله، ومن استهان به خسر؛ فاجعل تعظيمَ القرآنِ الذي كرّمه الله دأبك."}},{"n":14,"reflection":{"text":"«مرفوعة مطهرة»: تلك الصحفُ رفيعةُ القدرِ عالية، مطهّرةٌ عن الدنسِ والباطلِ لا يمسّها إلا المطهّرون؛ ففي هذا بيانُ رفعةِ القرآنِ وطهارته؛ فعظّم القرآنَ الرفيعَ الطاهرَ ولا تمسّه إلا على طهارة، فالقرآنُ رفيعٌ طاهر، فطهّر له نفسك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ رفعةِ القرآنِ وطهارتِه، وتطهّرُ النفسِ له."},"action":{"text":"تأمّل رفعةَ الصحفِ وطهارتها: مرفوعةٍ، أي تلك الصحفُ رفيعةُ القدرِ عاليةُ المنزلةِ عند الله، مرفوعةٌ في السماء، مطهّرةٍ، أي منزّهةٌ مطهّرةٌ عن الدنسِ والزيادةِ والنقصِ والباطل، لا يمسّها إلا المطهّرون من الملائكةِ (أو لا يمسّ القرآنَ إلا طاهر) «مرفوعة مطهرة»؛ ففي هذا بيانُ رفعةِ قدرِ القرآنِ وطهارته، إذ هو في صحفٍ مرفوعةٍ عاليةٍ مطهّرةٍ عن كلِّ دنس؛ فالقرآنُ رفيعُ القدرِ طاهرٌ منزّه؛ فعظّم أنت القرآنَ الرفيعَ الطاهر، وطهّر له نفسك وقلبك ولسانك، ولا تمسّ المصحفَ إلا على طهارة، ولا تتلُه إلا بقلبٍ حاضرٍ طاهر؛ لا يمسّه إلا المطهّرون؛ في صحفٍ مكرّمةٍ مرفوعةٍ مطهّرة؛ إنه لقرآنٌ كريم في كتابٍ مكنون لا يمسّه إلا المطهّرون؛ فالقرآنُ رفيعٌ طاهر، وتعظيمُه والتطهّرُ له واجب؛ فعظّمه، وطهّر له نفسك؛ فمن عظّم القرآنَ وتطهّر له انتفع، ومن استهان به حُرِم؛ فاجعل تعظيمَ رفعةِ القرآنِ والتطهّرَ له دأبك."}},{"n":15,"reflection":{"text":"«بأيدي سفرة»: تلك الصحفُ بأيدي الملائكةِ السفرةِ (الكتبةِ الناقلين للوحي بين الله ورسله)؛ ففي هذا بيانُ شرفِ حملةِ القرآنِ من الملائكة؛ فاقتدِ بالملائكةِ في حملِ القرآنِ وتبليغه، فحملةُ القرآنِ من الملائكةِ شرفاء، فاحمله بشرف.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاقتداءُ بالملائكةِ في حملِ القرآنِ وتبليغه."},"action":{"text":"تأمّل حملةَ الصحف: بأيدي سفرةٍ، أي تلك الصحفُ المكرّمةُ بأيدي السفرةِ من الملائكة، وهم الكتبةُ الناقلون للوحيِ بين الله ورسله، أو الملائكةُ الموكّلون بكتابةِ أعمالِ العباد؛ سُمّوا سفرةً لأنهم يسفرون بالوحي (ينقلونه) بين الله ورسله «بأيدي سفرة»؛ ففي هذا بيانُ شرفِ حملةِ القرآنِ من الملائكةِ السفرة، الذين ينقلون الوحيَ بأمانةٍ وطهارة؛ فحملةُ القرآنِ من الملائكةِ شرفاءُ كرام؛ فاقتدِ أنت بالملائكةِ في حملِ القرآنِ وتبليغه بأمانةٍ وطهارةٍ وإتقان، واحمل القرآنَ بشرفٍ كما تحمله الملائكةُ السفرة؛ نزل به الروحُ الأمين؛ كرامًا كاتبين يعلمون ما تفعلون؛ الماهرُ بالقرآنِ مع السفرةِ الكرامِ البررة؛ فحملةُ القرآنِ من الملائكةِ شرفاء، والاقتداءُ بهم في حمله؛ فاحمله بشرفٍ وأمانة، واقتدِ بهم؛ فمن حمل القرآنَ بشرفٍ شرُف، ومن أهمله خسر؛ فاجعل الاقتداءَ بالملائكةِ في حملِ القرآنِ دأبك."}},{"n":16,"reflection":{"text":"«كرام بررة»: تلك الملائكةُ كرامٌ على الله، بررةٌ أتقياءُ مطيعون؛ ففي هذا بيانُ كرمِ الملائكةِ حملةِ الوحيِ وبرّهم؛ فاطلب صحبةَ الكرامِ البررةِ بإتقانِ القرآن، فمن أتقن القرآنَ كان معهم، فأتقنه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ صحبةِ الملائكةِ الكرامِ بإتقانِ القرآنِ والبرّ."},"action":{"text":"تأمّل كرمَ الملائكةِ وبرّهم: كرامٍ، أي تلك الملائكةُ السفرةُ كرامٌ على الله، ذوو أخلاقٍ كريمةٍ وخصالٍ حميدة، بررةٍ، أي أتقياءُ صادقون مطيعون لله، كثيري الطاعةِ والبرّ، أبرارٌ في أعمالهم؛ فهم كرامٌ في أنفسهم بررةٌ في أعمالهم «كرام بررة»؛ ففي هذا بيانُ كرمِ الملائكةِ حملةِ الوحيِ وبرّهم وتقواهم، تشريفًا لهم ولِما يحملون من كلامِ الله؛ فالملائكةُ حملةُ الوحيِ كرامٌ بررةٌ أتقياء؛ فاطلب أنت صحبةَ هؤلاء الكرامِ البررةِ بإتقانِ القرآنِ حفظًا وتلاوةً وعملًا، والاتّصافِ بالبرِّ والتقوى، فإنّ الماهرَ بالقرآنِ معهم؛ الماهرُ بالقرآنِ مع السفرةِ الكرامِ البررة؛ بأيدي سفرةٍ كرامٍ بررة؛ بل عبادٌ مكرمون لا يسبقونه بالقولِ وهم بأمره يعملون؛ فالملائكةُ كرامٌ بررة، وصحبتهم تُطلَب بإتقانِ القرآنِ والبرّ؛ فأتقن القرآن، وبِرَّ، واطلب صحبتهم؛ فمن أتقن القرآنَ وبِرَّ كان معهم، ومن فرّط حُرِم؛ فاجعل طلبَ صحبةِ الكرامِ البررةِ بإتقانِ القرآنِ دأبك."}}]},{"title":"توبيخُ الإنسانِ الكفورِ وتذكيرُه بأطوارِ خلقه","range":[17,23],"theme":"توبيخُ الكفور «قتل الإنسان ما أكفره»، وتذكيرِه بأطوارِ خلقه «من نطفة خلقه فقدره ثم السبيل يسره ثم أماته فأقبره ثم إذا شاء أنشره»، وتقصيرِه «كلا لما يقض ما أمره»","verses":[{"n":17,"reflection":{"text":"«قتل الإنسان ما أكفره»: لُعِن الإنسانُ الكافر، ما أشدَّ كفرَه ونكرانَه لنعمِ ربّه؟ (دعاءٌ عليه وتعجّبٌ من كفره)؛ ففي هذا بيانُ ذمِّ كفرِ الإنسانِ ونكرانِه لنعمِ الله؛ فاحذر كفرَ النعمةِ الذي يُوجِب اللعن، بل اشكر ربّك، فكفرُ النعمةِ قبيح، فاشكر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمِ الله والحذرُ من كفرها."},"action":{"text":"تأمّل ذمَّ الكفور: قُتِل الإنسانُ، أي لُعِن الإنسانُ الكافرُ الجاحد، دعاءٌ عليه بأشنعِ الدعاء، ما أكفره، أي ما أشدَّ كفرَه ونكرانَه لنعمِ ربّه وجحوده لخالقه، تعجّبٌ من عظمِ كفره مع كثرةِ نعمِ الله عليه «قتل الإنسان ما أكفره»؛ ففي هذا بيانُ ذمِّ الله للإنسانِ الكافرِ الجاحدِ لنعمِ ربّه، والدعاءِ عليه، والتعجّبِ من شدّةِ كفره وكفرانِه مع إحسانِ الله إليه؛ فكفرُ النعمةِ وجحودُ الخالقِ قبيحٌ يُوجِب اللعن؛ فاحذر أنت كفرَ نعمةِ الله وجحودَ إحسانه، الذي يُوجِب اللعنَ والذمّ، بل اشكر ربّك على نعمه، واعرف فضله؛ إنّ الإنسانَ لكفور؛ وقليلٌ من عبادي الشكور؛ يعرفون نعمةَ الله ثم يُنكِرونها؛ فكفرُ النعمةِ قبيحٌ يُوجِب اللعن، والشكرُ سبيلُ الزيادة؛ فاشكر نعمَ الله، واحذر كفرها؛ فمن شكر زِيد، ومن كفر أُخِذ؛ فاجعل شكرَ نعمِ الله والحذرَ من كفرها دأبك."}},{"n":18,"reflection":{"text":"«من أي شيء خلقه»: من أيِّ شيءٍ حقيرٍ خلق الله هذا الإنسانَ المتكبّر؟ (تذكيرٌ بأصله الحقير)؛ ففي هذا بيانُ تذكيرِ الإنسانِ بأصله ليتواضع؛ فتأمّل أصلك الحقيرَ لتتواضع ولا تتكبّر، فأصلك حقيرٌ فتواضع، فاذكر أصلك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التواضعُ بتأمّلِ أصلِ الخلقِ الحقير."},"action":{"text":"تأمّل السؤالَ عن الأصل: من أيِّ شيءٍ، أي من أيِّ شيءٍ حقيرٍ ضعيف، خلقه، أي خلق الله هذا الإنسانَ الكفورَ المتكبّر؟ استفهامُ تعجيبٍ وتذكيرٍ بأصله الحقير، ليعلم أنه ليس أهلًا للكبرِ والكفر «من أي شيء خلقه»؛ ففي هذا بيانُ تذكيرِ الإنسانِ بأصله الحقير، تعجيبًا من كبره وكفره مع خسّةِ أصله، ليتواضع ويعرف قدره؛ فأصلُ الإنسانِ حقيرٌ يدعو إلى التواضعِ لا الكبر؛ فتأمّل أنت أصلك الحقيرَ (نطفةً مهينة) لتتواضع لله ولا تتكبّر ولا تكفر نعمه، فمن كان أصله ماءً مهينًا فلا يليق به الكبر؛ ألم نخلقكم من ماءٍ مهين؛ قُتِل الإنسانُ ما أكفره من أيِّ شيءٍ خلقه؛ فلينظر الإنسانُ ممّ خُلِق؛ فأصلُ الإنسانِ حقيرٌ يوجب التواضع؛ فتأمّله، وتواضع، ولا تتكبّر؛ فمن تأمّل أصله تواضع، ومن غفل تكبّر؛ فاجعل التواضعَ بتأمّلِ أصلِ الخلقِ دأبك."}},{"n":19,"reflection":{"text":"«من نطفة خلقه فقدره»: من نطفةٍ خلقه الله، فقدّره أطوارًا وقدّر خلقه وأعضاءه وأجله ورزقه؛ ففي هذا بيانُ عظمةِ قدرةِ الله في خلقِ الإنسانِ من نطفةٍ وتقديرِه؛ فتأمّل خلقك من نطفةٍ وتقديرَ الله لك، لتعرف قدرته وتشكره، فمن قدّرك يبعثك، فأيقن واشكر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تأمّلُ خلقِ الله وتقديرِه، وشكرُه واليقينُ ببعثه."},"action":{"text":"تأمّل الخلقَ والتقدير: من نطفةٍ، أي من ماءٍ مهينٍ ضعيف، خلقه، أي أوجده الله وأنشأه، فقدّره، أي قدّره أطوارًا (نطفةً فعلقةً فمضغةً)، وقدّر خلقه وأعضاءه وصورته وأجله ورزقه وسعادته أو شقاوته؛ فأحكم خلقه وتقديره «من نطفة خلقه فقدره»؛ ففي هذا بيانُ عظمةِ قدرةِ الله وحكمته في خلقِ الإنسانِ من نطفةٍ حقيرةٍ وتقديرِه وتصويرِه أطوارًا، وأنّ من قدر على ذلك قادرٌ على بعثه؛ فقدرةُ الله وتقديرُه في خلقِ الإنسانِ عظيمة؛ فتأمّل أنت خلقك من نطفةٍ وتقديرَ الله لك في أطوارك وأعضائك وأجلك ورزقك، لتعرف قدرته وحكمته، وتشكره، وتيقن بقدرته على بعثك؛ الذي خلق فسوّى والذي قدّر فهدى؛ إنا كلَّ شيءٍ خلقناه بقدر؛ ثم كان علقةً فخلق فسوّى؛ فقدرةُ الله وتقديرُه عظيمةٌ في خلقك، توجب الشكرَ واليقينَ بالبعث؛ فتأمّلها، واشكر، وأيقن؛ فمن تأمّلها شكر وأيقن، ومن غفل كفر؛ فاجعل تأمّلَ خلقِ الله وتقديرِه دأبك."}},{"n":20,"reflection":{"text":"«ثم السبيل يسره»: ثم يسّر له سبيلَ الخروجِ من بطنِ أمّه، أو سبيلَ الهدى والضلال ببيانِه؛ ففي هذا بيانُ نعمةِ تيسيرِ الله للإنسانِ سبيلَه؛ فاشكر تيسيرَ الله لك سبيلك، واسلك سبيلَ الهدى الذي يسّره، فالسبيلُ ميسَّرٌ فاسلكه، فاشكر واسلك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ تيسيرِ الله للسبيل، وسلوكُ سبيلِ الهدى."},"action":{"text":"تأمّل تيسيرَ السبيل: ثم السبيلَ يسّره، أي ثم يسّر الله له سبيلَ الخروجِ من بطنِ أمّه عند الولادة، أو يسّر له سبيلَ الهدى والضلالِ ببيانِه له بالرسلِ والعقلِ والفطرة، فهداه النجدين؛ فيسّر له السبيل «ثم السبيل يسره»؛ ففي هذا بيانُ نعمةِ الله في تيسيرِ السبيلِ للإنسان: سبيلِ خروجه إلى الدنيا، وسبيلِ الهدى ببيانه له؛ فتيسيرُ السبيلِ نعمةٌ من الله؛ فاشكر أنت نعمةَ الله في تيسيرِ سبيلك، واسلك سبيلَ الهدى الذي يسّره الله لك وبيّنه، ولا تسلك سبيلَ الضلال؛ وهديناه النجدين؛ إنا هديناه السبيلَ إمّا شاكرًا وإمّا كفورًا؛ الذي أعطى كلَّ شيءٍ خلقه ثم هدى؛ فتيسيرُ السبيلِ نعمةٌ، وسلوكُ الهدى واجب؛ فاشكرها، واسلك الهدى؛ فمن شكر وسلك الهدى اهتدى، ومن كفر وضلّ خسر؛ فاجعل شكرَ تيسيرِ السبيلِ وسلوكَ الهدى دأبك."}},{"n":21,"reflection":{"text":"«ثم أماته فأقبره»: ثم أماته الله فجعله ذا قبرٍ يُدفَن فيه (تكريمًا له)؛ ففي هذا بيانُ أنّ الموتَ والقبرَ من تدبيرِ الله وتكريمِه للإنسان؛ فتذكّر الموتَ والقبرَ اللذين كتبهما الله عليك، فاستعدّ للموتِ والقبر، فالموتُ حقٌّ فاستعدّ له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تذكّرُ الموتِ والقبرِ والاستعدادُ لهما."},"action":{"text":"تأمّل الموتَ والقبر: ثم أماته، أي ثم قبض الله روحه وأنهى أجله في الدنيا، فأقبره، أي جعله ذا قبرٍ يُدفَن فيه ويُوارى، ولم يجعله مُلقًى على وجهِ الأرضِ كالبهائم، تكريمًا لبني آدم؛ فأماته ثم أقبره «ثم أماته فأقبره»؛ ففي هذا بيانُ أنّ الموتَ والقبرَ من تدبيرِ الله وتقديرِه، وأنّ في القبرِ تكريمًا لبني آدم إذ يُوارَون؛ فالموتُ والقبرُ حقٌّ من تدبيرِ الله؛ فتذكّر أنت الموتَ والقبرَ اللذين كتبهما الله عليك، واستعدّ لهما بالإيمانِ والعملِ الصالحِ والتوبة، فإنّ القبرَ أوّلُ منازلِ الآخرة؛ كلُّ نفسٍ ذائقةُ الموت؛ حتى إذا جاء أحدهم الموت؛ ومن ورائهم برزخٌ إلى يومِ يُبعَثون؛ فالموتُ والقبرُ حقّ، والاستعدادُ لهما واجب؛ فتذكّرهما، واستعدّ، ولا تغفل؛ فمن استعدّ للموتِ والقبرِ أمِن، ومن غفل ندم؛ فاجعل تذكّرَ الموتِ والقبرِ والاستعدادَ لهما دأبك."}},{"n":22,"reflection":{"text":"«ثم إذا شاء أنشره»: ثم إذا شاء الله أحياه وبعثه من قبره (للحسابِ والجزاء)؛ ففي هذا بيانُ حتمِ البعثِ بمشيئةِ الله؛ فأيقن بأنّ الله سيبعثك من قبرك، واستعدّ للبعث، فالبعثُ حقٌّ بمشيئةِ الله، فاستعدّ له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعثِ والاستعدادُ له."},"action":{"text":"تأمّل البعثَ: ثم إذا شاء، الله، في الوقتِ الذي يشاء (يومَ القيامة)، وأنشره، أي أحياه وبعثه من قبره ونشره للحسابِ والجزاء؛ فالبعثُ بمشيئةِ الله وقدرته «ثم إذا شاء أنشره»؛ ففي هذا بيانُ حتمِ البعثِ بمشيئةِ الله، فالذي خلق الإنسانَ من نطفةٍ وقدّره ويسّر سبيله وأماته وأقبره قادرٌ على إنشاره وبعثه؛ فالبعثُ حقٌّ بمشيئةِ الله وقدرته؛ فأيقن أنت بأنّ الله سيبعثك من قبرك للحسابِ والجزاء، واستعدّ للبعثِ بالإيمانِ والعملِ الصالح، فمن قدر على البدءِ قدر على الإعادة؛ وهو الذي يبدأ الخلقَ ثم يعيده وهو أهونُ عليه؛ ونُفِخ في الصورِ فإذا هم من الأجداثِ إلى ربّهم ينسلون؛ منها خلقناكم وفيها نعيدكم ومنها نخرجكم تارةً أخرى؛ فالبعثُ حقٌّ بمشيئةِ الله، فالاستعدادُ له واجب؛ فأيقن به، واستعدّ، واعمل؛ فمن أيقن بالبعثِ استعدّ، ومن أنكره خسر؛ فاجعل اليقينَ بالبعثِ والاستعدادَ له دأبك."}},{"n":23,"reflection":{"text":"«كلا لما يقض ما أمره»: حقًّا، لم يقض الإنسانُ ولم يؤدِّ ما أمره الله به (فقصّر في حقّ ربّه)؛ ففي هذا بيانُ تقصيرِ الإنسانِ في أداءِ ما أُمِر به رغم النعم؛ فأدِّ ما أمرك الله به ولا تقصّر، فالتقصيرُ في أمرِ الله مذموم، فبادر بأداءِ حقّه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أداءُ ما أمر الله به وعدمُ التقصيرِ في حقّه."},"action":{"text":"تأمّل التقصير: كلّا، أي حقًّا، ردعًا وتنبيهًا، لمّا يقضِ، أي لم يقض الإنسانُ ولم يؤدِّ بعدُ، ما أمره، أي ما أمره الله به من الإيمانِ والطاعةِ وأداءِ حقوقه؛ فقصّر في أداءِ ما أُمِر به رغم كثرةِ نعمِ الله عليه «كلا لما يقض ما أمره»؛ ففي هذا بيانُ تقصيرِ الإنسانِ في أداءِ ما أمره الله به من العبادةِ والطاعةِ وشكرِ النعم، رغم إحسانِ الله إليه في خلقه ورزقه؛ فالإنسانُ مقصّرٌ في أداءِ حقِّ ربّه؛ فأدِّ أنت ما أمرك الله به من الإيمانِ والطاعةِ وأداءِ الحقوقِ وشكرِ النعم، ولا تقصّر في حقّ ربّك رغم نعمه عليك، وحاسب نفسك على تقصيرك؛ وما خلقتُ الجنَّ والإنسَ إلا ليعبدون؛ يا أيها الإنسانُ ما غرّك بربّك الكريم؛ فبادروا بالأعمال؛ فالتقصيرُ في أمرِ الله مذموم، وأداؤه واجب؛ فأدِّ ما أُمِرت به، ولا تقصّر، وحاسب نفسك؛ فمن أدّى ما أُمِر به أفلح، ومن قصّر خسر؛ فاجعل أداءَ ما أمر الله به دأبك."}}]},{"title":"الاستدلالُ بنعمِ الطعامِ والنباتِ على القدرة","range":[24,32],"theme":"الأمرُ بالنظرِ في الطعام «فلينظر الإنسان إلى طعامه أنا صببنا الماء صبا ثم شققنا الأرض شقا فأنبتنا فيها حبا وعنبا وقضبا وزيتونا ونخلا وحدائق غلبا وفاكهة وأبا متاعا لكم ولأنعامكم»","verses":[{"n":24,"reflection":{"text":"«فلينظر الإنسان إلى طعامه»: فلينظر الإنسانُ إلى طعامه: كيف خلقه الله وهيّأه له؟ ففي هذا بيانُ الأمرِ بالنظرِ في الطعامِ آيةً على قدرةِ الله ونعمته؛ فتأمّل طعامك آيةً على قدرةِ الله ورحمته، فالطعامُ نعمةٌ وآية، فتأمّله واشكر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في نعمةِ الطعامِ آيةً على القدرةِ والرحمة، وشكرُها."},"action":{"text":"تأمّل الأمرَ بالنظرِ في الطعام: فلينظر الإنسانُ، أي فليتأمّل ولينظر نظرَ اعتبارٍ، إلى طعامه، الذي يأكله ويقتات به، كيف خلقه الله وهيّأه له، ومن أين جاء، وكيف تدرّج من نطفةِ الماءِ إلى الحبِّ والثمر؛ فليعتبر بذلك على قدرةِ الله ونعمته «فلينظر الإنسان إلى طعامه»؛ ففي هذا بيانُ الأمرِ بالنظرِ والتأمّلِ في الطعامِ الذي يقتات به الإنسان، فإنّ في تكوّنه وخروجه من الأرضِ بالماءِ عبرةً ونعمةً وآيةً على قدرةِ الله ورحمته وحكمته؛ فالطعامُ نعمةٌ وآيةٌ تدعو إلى النظرِ والشكر؛ فتأمّل أنت طعامك الذي تأكله، كيف خلقه الله وهيّأه، واعتبر به على قدرةِ الله ورحمته، واشكر نعمة الطعام؛ فلينظر الإنسانُ ممّ خُلِق؛ أفلا ينظرون إلى الإبلِ كيف خُلِقت؛ وآيةٌ لهم الأرضُ الميتةُ أحييناها وأخرجنا منها حبًّا؛ فالطعامُ نعمةٌ وآيةٌ تستوجب النظرَ والشكر؛ فتأمّله، واعتبر به، واشكر؛ فمن تأمّل واعتبر وشكر اهتدى، ومن غفل كفر؛ فاجعل التأمّلَ في نعمةِ الطعامِ وشكرَها دأبك."}},{"n":25,"reflection":{"text":"«أنا صببنا الماء صبا»: أنّا صببنا الماءَ (المطر) صبًّا كثيرًا من السماء؛ ففي هذا بيانُ نعمةِ الماءِ الذي هو أصلُ الطعام؛ فاشكر نعمةَ الماءِ الذي به حياةُ طعامك، فالماءُ نعمةٌ وأصلُ الحياة، فاشكره واعتبر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ الماءِ والاعتبارُ به أصلَ الحياة."},"action":{"text":"تأمّل صبَّ الماء: أنّا صببنا الماءَ صبًّا، أي بيانُ كيفيّةِ خلقِ الطعام: أنّا أنزلنا الماءَ (المطر) من السماءِ وصببناه صبًّا كثيرًا متتابعًا على الأرض، فكان أصلًا لحياةِ النبات؛ فالماءُ أوّلُ أسبابِ الطعام «أنا صببنا الماء صبا»؛ ففي هذا بيانُ نعمةِ الله في صبِّ الماءِ من السماء، الذي هو أصلُ حياةِ النباتِ والطعامِ والأحياء، وهو آيةٌ على قدرته ورحمته؛ فالماءُ نعمةٌ وأصلُ حياةِ الطعامِ والأحياء؛ فاشكر أنت نعمةَ الماءِ الذي به حياةُ طعامك ونباتك وحياتك، واعتبر به على قدرةِ الله ورحمته، فلولا الماءُ لهلك كلُّ شيء؛ وجعلنا من الماءِ كلَّ شيءٍ حيّ؛ وأنزلنا من السماءِ ماءً بقدرٍ فأسكنّاه في الأرض؛ أفرأيتم الماءَ الذي تشربون؛ فالماءُ نعمةٌ وأصلُ الحياة، يستوجب الشكرَ والاعتبار؛ فاشكره، واعتبر به؛ فمن شكر واعتبر اهتدى، ومن غفل كفر؛ فاجعل شكرَ نعمةِ الماءِ والاعتبارَ به دأبك."}},{"n":26,"reflection":{"text":"«ثم شققنا الأرض شقا»: ثم شققنا الأرضَ شقًّا بالنباتِ الذي يخرج منها؛ ففي هذا بيانُ نعمةِ إخراجِ النباتِ من الأرضِ آيةً على قدرةِ الله؛ فتأمّل شقَّ الأرضِ بالنباتِ آيةً على قدرةِ الله على البعث، فمن شقّ الأرضَ بالنباتِ يبعثك، فأيقن واشكر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بشقِّ الأرضِ بالنباتِ آيةً على القدرةِ والبعث."},"action":{"text":"تأمّل شقَّ الأرض: ثم شققنا الأرضَ شقًّا، أي ثم صدّعنا الأرضَ وشققناها بما يخرج منها من النباتِ والزرعِ والشجر، فتنشقّ عن النباتِ الذي أودعناه فيها بالماء؛ فشُقّت الأرضُ بالنبات «ثم شققنا الأرض شقا»؛ ففي هذا بيانُ نعمةِ الله في إخراجِ النباتِ من الأرضِ بشقّها، وما في ذلك من القدرةِ والحكمةِ والرحمة، وهو آيةٌ على قدرته على البعث (إخراجِ الموتى من الأرضِ كإخراجِ النبات)؛ فشقُّ الأرضِ بالنباتِ آيةٌ على القدرةِ والبعث؛ فتأمّل أنت شقَّ الأرضِ بالنباتِ آيةً على قدرةِ الله وحكمته وقدرته على إخراجك من الأرضِ للبعث؛ فأنبتنا فيها حبًّا؛ وآيةٌ لهم الأرضُ الميتةُ أحييناها؛ كذلك تُخرَجون؛ فشقُّ الأرضِ بالنباتِ نعمةٌ وآيةٌ على البعث؛ فتأمّله، واعتبر به، وأيقن؛ فمن اعتبر أيقن، ومن غفل جهل؛ فاجعل الاعتبارَ بشقِّ الأرضِ بالنباتِ دأبك."}},{"n":27,"reflection":{"text":"«فأنبتنا فيها حبا»: فأنبتنا في الأرضِ حبًّا (كالبرِّ والشعيرِ يُقتاتُ به)؛ ففي هذا بيانُ نعمةِ إنباتِ الحبِّ قوتًا للناس؛ فاشكر نعمةَ الحبِّ الذي يقيتك، فالحبُّ نعمةٌ وقوت، فاشكره واعتبر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ الحبِّ الذي هو قوتُ الناس."},"action":{"text":"تأمّل نعمةَ الحبّ: فأنبتنا فيها، في الأرضِ المشقوقة، حبًّا، أي حبوبًا كثيرةً متنوّعةً كالبرِّ والشعيرِ والأرزِّ وسائرِ ما يُقتاتُ به من الحبوب؛ فأخرج الله الحبَّ قوتًا للناس «فأنبتنا فيها حبا»؛ ففي هذا بيانُ نعمةِ الله في إنباتِ الحبِّ من الأرض، الذي هو قوتُ الناسِ الأساسيّ، وهو نعمةٌ وآيةٌ على قدرته ورحمته؛ فالحبُّ نعمةٌ وقوتٌ يستوجب الشكر؛ فاشكر أنت نعمةَ الحبِّ الذي يقيتك ويحفظ حياتك، واعتبر به على قدرةِ الله ورحمته، ووظّف قوّتك التي منه في طاعته؛ والحبُّ ذو العصفِ والريحان؛ فأخرجنا منه خضرًا نخرج منه حبًّا متراكبًا؛ وجناتٍ من أعنابٍ وزرعٍ ونخيل؛ فالحبُّ نعمةٌ وقوتٌ يستوجب الشكرَ والاعتبار؛ فاشكره، واعتبر به؛ فمن شكر واعتبر اهتدى، ومن غفل كفر؛ فاجعل شكرَ نعمةِ الحبِّ دأبك."}},{"n":28,"reflection":{"text":"«وعنبا وقضبا»، وأنبتنا عنبًا (كرومًا) وقضبًا (رطبةً وعلفًا يُقطَع للدوابّ)؛ ففي هذا بيانُ نعمةِ العنبِ والعلفِ للإنسانِ والحيوان؛ فاشكر نعمةَ العنبِ والعلفِ التي يتغذّى بها أنت وأنعامك، فهما نعمة، فاشكرهما.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ العنبِ والعلفِ للإنسانِ والحيوان."},"action":{"text":"تأمّل نعمةَ العنبِ والقضب: وعنبًا، أي وأنبتنا فيها كرومَ العنبِ اللذيذِ الذي يُؤكَل طريًّا ويابسًا ويُعصَر، وقضبًا، أي القتَّ (الرطبةَ) وما يُقطَع من العلفِ ويُجزّ للدوابِّ رطبًا، ثم ينبت ثانية «وعنبا وقضبا»؛ ففي هذا بيانُ نعمةِ الله في إنباتِ العنبِ (غذاءِ الإنسان) والقضبِ (علفِ الحيوان)، وهما نعمةٌ وآيةٌ على قدرته ورحمته وحكمته في تنويعِ الأقوات؛ فالعنبُ والعلفُ نعمةٌ للإنسانِ والحيوان؛ فاشكر أنت نعمةَ العنبِ الذي تأكله والعلفِ الذي يتغذّى به أنعامك، واعتبر بها على قدرةِ الله ورحمته وحكمته؛ ومن ثمراتِ النخيلِ والأعنابِ تتّخذون منه سكرًا ورزقًا حسنًا؛ وجعلنا فيها جناتٍ من نخيلٍ وأعناب؛ كلوا وارعوا أنعامكم؛ فالعنبُ والعلفُ نعمةٌ تستوجب الشكرَ والاعتبار؛ فاشكرهما، واعتبر بهما؛ فمن شكر واعتبر اهتدى، ومن غفل كفر؛ فاجعل شكرَ نعمةِ العنبِ والعلفِ دأبك."}},{"n":29,"reflection":{"text":"«وزيتونا ونخلا»، وأنبتنا زيتونًا (يُؤكَل ويُعصَر زيته) ونخلًا (يُؤكَل تمره)؛ ففي هذا بيانُ نعمةِ الزيتونِ والنخلِ للإنسان؛ فاشكر نعمةَ الزيتونِ والنخلِ ومنافعِهما، فهما نعمةٌ وبركة، فاشكرهما.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ الزيتونِ والنخلِ ومنافعهما."},"action":{"text":"تأمّل نعمةَ الزيتونِ والنخل: وزيتونًا، أي وأنبتنا شجرَ الزيتونِ الذي يُؤكَل ثمره ويُعصَر منه الزيتُ المبارك، فيه غذاءٌ وإدامٌ ودواءٌ وسراج، ونخلًا، أي شجرَ النخلِ الذي يُؤكَل تمره وبلحه وينتفع بجميعِ أجزائه؛ فأنبت الله الزيتونَ والنخل «وزيتونا ونخلا»؛ ففي هذا بيانُ نعمةِ الله في إنباتِ الزيتونِ والنخل، وما فيهما من المنافعِ والبركةِ والغذاء، وهما نعمةٌ وآيةٌ على قدرته ورحمته؛ فالزيتونُ والنخلُ نعمةٌ وبركةٌ ومنفعة؛ فاشكر أنت نعمةَ الزيتونِ والنخلِ ومنافعِهما، واعتبر بهما على قدرةِ الله ورحمته، وانتفع بهما في الحلال؛ يُنبِت لكم به الزرعَ والزيتونَ والنخيلَ والأعناب؛ ومن ثمراتِ النخيلِ والأعناب؛ والتينِ والزيتون؛ فالزيتونُ والنخلُ نعمةٌ تستوجب الشكرَ والاعتبار؛ فاشكرهما، واعتبر بهما؛ فمن شكر واعتبر اهتدى، ومن غفل كفر؛ فاجعل شكرَ نعمةِ الزيتونِ والنخلِ دأبك."}},{"n":30,"reflection":{"text":"«وحدائق غلبا»، وأنبتنا حدائقَ (بساتينَ) غُلبًا (عظيمةَ الأشجارِ ملتفّةً)؛ ففي هذا بيانُ نعمةِ الحدائقِ الملتفّةِ العظيمة؛ فاشكر نعمةَ الحدائقِ والبساتينِ التي يُخرِجها الله، فهي نعمةٌ وجمال، فاشكرها واعتبر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ الحدائقِ والبساتينِ والاعتبارُ بها."},"action":{"text":"تأمّل نعمةَ الحدائق: وحدائقَ، أي وبساتينَ جامعةً لأنواعِ الأشجارِ والثمارِ محوطةً، غُلبًا، أي عظيمةَ الأشجارِ غليظةَ الجذوعِ ملتفّةً كثيفةً كثيرةَ الأشجار؛ فأنبت الله الحدائقَ العظيمةَ الملتفّة «وحدائق غلبا»؛ ففي هذا بيانُ نعمةِ الله في إنباتِ الحدائقِ العظيمةِ الملتفّةِ الكثيفة، وما فيها من الثمارِ والمنافعِ والجمال، وهي نعمةٌ وآيةٌ على قدرته ورحمته وكرمه؛ فالحدائقُ الملتفّةُ نعمةٌ وجمالٌ وآية؛ فاشكر أنت نعمةَ الحدائقِ والبساتينِ التي يُخرِجها الله بالماء، واعتبر بها على قدرةِ الله ورحمته وكرمه؛ فأنبتنا به حدائقَ ذاتَ بهجة؛ وجناتٍ ألفافًا؛ جناتٍ وأعنابًا؛ فالحدائقُ نعمةٌ وجمالٌ يستوجب الشكرَ والاعتبار؛ فاشكرها، واعتبر بها؛ فمن شكر واعتبر اهتدى، ومن غفل كفر؛ فاجعل شكرَ نعمةِ الحدائقِ دأبك."}},{"n":31,"reflection":{"text":"«وفاكهة وأبا»، وأنبتنا فاكهةً (تُؤكَل تلذّذًا) وأبًّا (كلأً ومرعًى للأنعام)؛ ففي هذا بيانُ نعمةِ الفاكهةِ والمرعى للإنسانِ والحيوان؛ فاشكر نعمةَ الفاكهةِ والمرعى التي يتغذّى بها أنت وأنعامك، فهما نعمة، فاشكرهما.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ الفاكهةِ والمرعى للإنسانِ والحيوان."},"action":{"text":"تأمّل نعمةَ الفاكهةِ والأبّ: وفاكهةً، أي وأنبتنا فاكهةً كثيرةً متنوّعةً يتلذّذ بها الناسُ ويتفكّهون، وأبًّا، أي كلأً ومرعًى ونباتًا ترعاه الأنعامُ والدوابّ، ممّا لا يأكله الناسُ؛ فأنبت الله الفاكهةَ للناسِ والأبَّ للأنعام «وفاكهة وأبا»؛ ففي هذا بيانُ نعمةِ الله في إنباتِ الفاكهةِ (متعةِ الإنسان) والأبِّ (رزقِ الأنعام)، وهما نعمةٌ وآيةٌ على قدرته ورحمته وحكمته في تدبيرِ أرزاقِ الخلق؛ فالفاكهةُ والمرعى نعمةٌ للإنسانِ والحيوان؛ فاشكر أنت نعمةَ الفاكهةِ التي تأكلها والمرعى الذي ترعاه أنعامك، واعتبر بها على قدرةِ الله ورحمته وحكمته، وانتفع بها في الحلال؛ وفاكهةٍ كثيرةٍ لا مقطوعةٍ ولا ممنوعة؛ كلوا وارعوا أنعامكم؛ فيها فاكهةٌ والنخلُ ذاتُ الأكمام؛ فالفاكهةُ والمرعى نعمةٌ تستوجب الشكرَ والاعتبار؛ فاشكرهما، واعتبر بهما؛ فمن شكر واعتبر اهتدى، ومن غفل كفر؛ فاجعل شكرَ نعمةِ الفاكهةِ والمرعى دأبك."}},{"n":32,"reflection":{"text":"«متاعا لكم ولأنعامكم»: جعل ذلك كلَّه متاعًا ومنفعةً لكم ولأنعامكم؛ ففي هذا بيانُ أنّ نعمَ النباتِ متاعٌ للإنسانِ والحيوان؛ فاشكر نعمَ الله التي جعلها متاعًا لك ولأنعامك، ووظّفها في طاعته، فنعمُ الله متاعٌ للشكر، فاشكرها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمِ الله وتوظيفُها في طاعته."},"action":{"text":"تأمّل غايةَ النعم: متاعًا لكم، أي جعل الله ذلك كلَّه (الحبَّ والعنبَ والزيتونَ والنخلَ والحدائقَ والفاكهةَ والأبَّ) متاعًا ومنفعةً وبلغةً لكم، أيها الناسُ، ولأنعامكم، أي وللأنعامِ التي تنتفعون بها؛ فكلُّ ذلك نعمةٌ ومتاعٌ لمنفعتكم ومنفعةِ أنعامكم «متاعا لكم ولأنعامكم»؛ ففي هذا بيانُ أنّ الله جعل نعمَ النباتِ متاعًا ومنفعةً للإنسانِ وأنعامِه، رحمةً بهم، فتستوجب الشكر؛ فنعمُ الله متاعٌ ومنفعةٌ تستوجب الشكرَ والطاعة؛ فاشكر أنت نعمَ الله التي جعلها متاعًا لك ولأنعامك، ووظّفها في طاعته لا في معصيته، ولا تكفرها ولا تطغَ بها؛ فاكهةً وأبًّا متاعًا لكم ولأنعامكم؛ كلوا وارعوا أنعامكم؛ وآتاكم من كلِّ ما سألتموه؛ فنعمُ الله متاعٌ للانتفاعِ والشكر؛ فاشكرها، ووظّفها في الطاعة، ولا تكفرها؛ فمن شكر ووظّف النعمَ في الطاعةِ بورك له، ومن كفرها أُخِذ؛ فاجعل شكرَ نعمِ الله وتوظيفَها في طاعته دأبك."}}]},{"title":"الصاخّةُ ويومُ الفرارِ وانقسامُ الوجوه","range":[33,42],"theme":"مجيءُ الصاخّة «فإذا جاءت الصاخة يوم يفر المرء من أخيه وأمه وأبيه وصاحبته وبنيه لكل امرئ منهم يومئذ شأن يغنيه»، وانقسامِ الوجوه «وجوه يومئذ مسفرة ضاحكة مستبشرة ووجوه يومئذ عليها غبرة ترهقها قترة أولئك هم الكفرة الفجرة»","verses":[{"n":33,"reflection":{"text":"«فإذا جاءت الصاخة»: فإذا جاءت الصيحةُ الصاخّةُ التي تصمّ الآذانَ لشدّتها (النفخةُ الثانية، أو القيامة)؛ ففي هذا بيانُ عظمِ هولِ القيامةِ التي تصمّ الأسماع؛ فاستعدّ للصاخّةِ التي تصمّ الآذان، فالقيامةُ صاخّةٌ عظيمة، فاعمل لها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للصاخّةِ (القيامة)."},"action":{"text":"تأمّل الصاخّة: فإذا جاءت الصاخّةُ، أي فإذا جاءت الصيحةُ العظيمةُ (النفخةُ الثانيةُ في الصور، أو القيامة) التي تصخّ الآذانَ وتصمّها لشدّتها وهولها، فتكاد تُصِمّ الأسماعَ من شدّةِ وقعها؛ سُمّيت صاخّةً لأنها تصخّ الأسماع «فإذا جاءت الصاخة»؛ ففي هذا بيانُ عظمِ هولِ القيامة، وأنها الصاخّةُ التي تصمّ الآذانَ لشدّتها؛ فالقيامةُ صاخّةٌ عظيمةٌ تصمّ الأسماع؛ فاستعدّ أنت للصاخّةِ (القيامة) التي تصمّ الآذانَ من هولها، بالإيمانِ والعملِ الصالحِ قبل مجيئها؛ فإذا جاءت الطامّةُ الكبرى؛ يومَ يُنفَخ في الصور؛ القارعةُ ما القارعة؛ فالقيامةُ صاخّةٌ عظيمة، فالاستعدادُ لها واجب؛ فاستعدّ، واعمل، ولا تسوّف؛ فمن استعدّ لها أمِن، ومن غفل فوجئ؛ فاجعل الاستعدادَ للصاخّةِ دأبك."}},{"n":34,"reflection":{"text":"«يوم يفر المرء من أخيه»: يومَ يفرّ المرءُ من أخيه (من شدّةِ الهول، وخوفَ مطالبته بحقّ)؛ ففي هذا بيانُ شدّةِ هولِ القيامةِ حتى يفرّ المرءُ من أقرب الناس؛ فاعمل لِما ينجّيك يومَ يفرّ الأخُ من أخيه، فلا ينفع يومئذٍ قريب، فاعمل لنفسك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للنفسِ يومَ يفرّ المرءُ من أقربِ الناس."},"action":{"text":"تأمّل الفرارَ من الأخ: يومَ يفرّ المرءُ من أخيه، أي يومَ القيامةِ يفرّ الإنسانُ من أخيه (أقربِ الناسِ نسبًا بعد الوالدِ والولد)، من شدّةِ الهول، وخوفَ أن يطالبه بحقٍّ أو مظلمة، وانشغالًا بنفسه «يوم يفر المرء من أخيه»؛ ففي هذا بيانُ شدّةِ هولِ يومِ القيامة، حتى يفرّ المرءُ من أخيه الذي كان يأنس به، لِما هو فيه من الشغلِ بنفسه والخوفِ من المطالبة؛ فهولُ القيامةِ يفرّق بين أقربِ الناس؛ فاعمل أنت لِما ينجّيك يومَ يفرّ الأخُ من أخيه، فإنه لا ينفعك يومئذٍ قريبٌ ولا حبيب، بل عملك الصالح؛ ولا يسأل حميمٌ حميمًا يبصّرونهم؛ يوم لا ينفع مالٌ ولا بنون إلا من أتى الله بقلبٍ سليم؛ فأنساب بينهم يومئذٍ ولا يتساءلون؛ فهولُ القيامةِ يفرّق الأقارب، والنجاةُ بالعملِ لا بالقرابة؛ فاعمل لنفسك، واحرص على النجاة، ولا تعتمد على قريب؛ فمن عمل لنفسه نجا، ومن اتّكل على غيره خسر؛ فاجعل العملَ للنفسِ يومَ الفرارِ دأبك."}},{"n":35,"reflection":{"text":"«وأمه وأبيه»، ويفرّ من أمّه وأبيه (مع عظمِ حقّهما) من شدّةِ الهول؛ ففي هذا بيانُ زيادةِ شدّةِ الهولِ حتى يفرّ من الوالدين؛ فاعمل لِما ينجّيك يومَ يفرّ الولدُ من والديه، فلا ينفع يومئذٍ والدٌ ولا ولد، فاعمل لنفسك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للنفسِ يومَ يفرّ المرءُ من والديه."},"action":{"text":"تأمّل الفرارَ من الوالدين: وأمّه وأبيه، أي ويفرّ المرءُ يومَ القيامةِ من أمّه وأبيه، مع عظمِ حقّهما عليه وشدّةِ محبّته لهما في الدنيا، لِما هو فيه من شدّةِ الهولِ والشغلِ بنفسه؛ فالفرارُ يزداد شدّةً بالفرارِ من الوالدين «وأمه وأبيه»؛ ففي هذا بيانُ زيادةِ شدّةِ هولِ يومِ القيامة، حتى يفرّ المرءُ من والديه اللذين هما أعزُّ الناسِ عليه، لِما هو فيه من الكرب؛ فهولُ القيامةِ يفرّق حتى بين الولدِ ووالديه؛ فاعمل أنت لِما ينجّيك يومَ يفرّ الولدُ من والديه، فإنه لا ينفعك يومئذٍ والدٌ ولا ولد، بل عملك؛ يا أيها الناسُ اتّقوا ربّكم واخشوا يومًا لا يجزي والدٌ عن ولده ولا مولودٌ هو جازٍ عن والده شيئًا؛ لن تنفعكم أرحامكم ولا أولادكم يومَ القيامة؛ فهولُ القيامةِ يفرّق الوالدَ والولد، والنجاةُ بالعمل؛ فاعمل لنفسك، ولا تعتمد على والدٍ ولا ولد؛ فمن عمل لنفسه نجا، ومن اتّكل على غيره خسر؛ فاجعل العملَ للنفسِ يومَ الفرارِ دأبك."}},{"n":36,"reflection":{"text":"«وصاحبته وبنيه»، ويفرّ من زوجته وبنيه (مع شدّةِ التعلّقِ بهم) من شدّةِ الهول؛ ففي هذا بيانُ تمامِ شدّةِ الهولِ حتى يفرّ من الزوجةِ والولد؛ فاعمل لِما ينجّيك يومَ يفرّ المرءُ من أهله وولده، فلا ينفع يومئذٍ أهلٌ ولا ولد، فاعمل لنفسك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للنفسِ يومَ يفرّ المرءُ من زوجه وولده."},"action":{"text":"تأمّل الفرارَ من الزوجةِ والولد: وصاحبته، أي زوجته التي كان يسكن إليها ويأنس بها، وبنيه، أي أولاده الذين هم أحبُّ الناسِ إليه؛ يفرّ منهم يومَ القيامةِ من شدّةِ الهولِ والشغلِ بنفسه، مع شدّةِ تعلّقه بهم في الدنيا «وصاحبته وبنيه»؛ ففي هذا بيانُ تمامِ شدّةِ هولِ يومِ القيامة، حتى يفرّ المرءُ من زوجته وبنيه الذين هم أعلقُ الناسِ بقلبه، لِما هو فيه من الكرب؛ فهولُ القيامةِ يفرّق حتى بين المرءِ وأهلِه وولده؛ فاعمل أنت لِما ينجّيك يومَ يفرّ المرءُ من أهله وولده، فإنه لا ينفعك يومئذٍ زوجٌ ولا ولد، بل عملك الصالح؛ يوم لا ينفع مالٌ ولا بنون؛ إنّ من أزواجكم وأولادكم عدوًّا لكم فاحذروهم؛ ولا تنفعكم أرحامكم ولا أولادكم يومَ القيامة؛ فهولُ القيامةِ يفرّق الأهلَ والولد، والنجاةُ بالعمل؛ فاعمل لنفسك، ولا تعتمد على أهلٍ ولا ولد؛ فمن عمل لنفسه نجا، ومن اتّكل على أهله خسر؛ فاجعل العملَ للنفسِ يومَ الفرارِ دأبك."}},{"n":37,"reflection":{"text":"«لكل امرئ منهم يومئذ شأن يغنيه»: لكلِّ واحدٍ منهم يومئذٍ حالٌ وشغلٌ يشغله عن غيره ويكفيه همًّا (من هولِ موقفه)؛ ففي هذا بيانُ انشغالِ كلِّ نفسٍ بنفسها يومَ القيامة؛ فاعمل لنفسك فإنّ كلَّ نفسٍ يومئذٍ مشغولةٌ بشأنها، فلا معينَ يومئذٍ إلا العمل، فاعمل لنفسك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للنفسِ لانشغالِ كلِّ نفسٍ بشأنها يومَ القيامة."},"action":{"text":"تأمّل انشغالَ كلِّ نفس: لكلِّ امرئٍ منهم، أي من هؤلاء الفارّين، يومئذٍ، يومَ القيامةِ، شأنٌ يغنيه، أي حالٌ وشغلٌ عظيمٌ يشغله عن كلِّ أحدٍ ويكفيه همًّا، فلا يلتفت إلى غيره ولو كان أقربَ الناسِ إليه، لعظمِ ما هو فيه من الكرب؛ فكلُّ نفسٍ مشغولةٌ بشأنها «لكل امرئ منهم يومئذ شأن يغنيه»؛ ففي هذا بيانُ أنّ كلَّ نفسٍ يومَ القيامةِ مشغولةٌ بشأنها وحالها، لا تلتفت إلى غيرها، لعظمِ الهول؛ فلا يهمّ أحدًا إلا نفسه؛ فاعمل أنت لنفسك، فإنّ كلَّ نفسٍ يومئذٍ مشغولةٌ بشأنها، ولا يعينك يومئذٍ إلا عملك الصالح، فقدّم لنفسك؛ نفسي نفسي (يقولها الأنبياءُ يومَ المحشر)؛ كلُّ نفسٍ بما كسبت رهينة؛ ولا تزر وازرةٌ وزرَ أخرى؛ فكلُّ نفسٍ مشغولةٌ بشأنها، والنجاةُ بالعملِ لا بالغير؛ فاعمل لنفسك، وقدّم لها، ولا تعتمد على أحد؛ فمن عمل لنفسه نجا، ومن اتّكل على غيره خسر؛ فاجعل العملَ للنفسِ دأبك."}},{"n":38,"reflection":{"text":"«وجوه يومئذ مسفرة»، وجوهُ المؤمنين يومئذٍ مشرقةٌ مضيئةٌ مستنيرة؛ ففي هذا بيانُ إشراقِ وجوهِ أهلِ السعادةِ يومَ القيامة؛ فاعمل لتكون وجهك من المسفرةِ المشرقة، فإشراقُ الوجهِ يومئذٍ ثمرةُ الإيمانِ والعمل، فاعمل لها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لإشراقِ الوجهِ يومَ القيامة."},"action":{"text":"تأمّل إشراقَ الوجوه: وجوهٌ يومئذٍ، يومَ القيامةِ، مسفرةٌ، أي مشرقةٌ مضيئةٌ مستنيرةٌ حسنةٌ، قد علاها النورُ والبهجةُ والسرور؛ وهي وجوهُ المؤمنين السعداء «وجوه يومئذ مسفرة»؛ ففي هذا بيانُ حالِ وجوهِ أهلِ السعادةِ يومَ القيامة: إشراقٌ ونورٌ وبهجة، جزاءَ إيمانهم وعملهم؛ فإشراقُ الوجهِ يومئذٍ ثمرةُ الإيمانِ والعملِ الصالح؛ فاعمل أنت لتكون وجهك من الوجوهِ المسفرةِ المشرقةِ يومَ القيامة، بالإيمانِ والعملِ الصالحِ والتقوى؛ وجوهٌ يومئذٍ ناضرةٌ إلى ربّها ناظرة؛ تعرف في وجوههم نضرةَ النعيم؛ يومَ تبيضّ وجوه؛ فإشراقُ الوجوهِ يومَ القيامةِ لأهلِ الإيمانِ والعمل؛ فاعمل لها، وآمن، واتّقِ؛ فمن آمن وعمل أشرق وجهه، ومن كفر اسودّ وجهه؛ فاجعل العملَ لإشراقِ الوجهِ دأبك."}},{"n":39,"reflection":{"text":"«ضاحكة مستبشرة»: ضاحكةٌ فرحةٌ مستبشرةٌ بما نالت من رحمةِ الله ونعيمه؛ ففي هذا بيانُ تمامِ سرورِ أهلِ السعادةِ يومَ القيامة؛ فاعمل لتكون من الضاحكين المستبشرين يومَ القيامة، فالسرورُ يومئذٍ ثمرةُ العمل، فاعمل له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للسرورِ والاستبشارِ يومَ القيامة."},"action":{"text":"تأمّل سرورَ الوجوه: ضاحكةٌ، أي فرحةٌ ضاحكةٌ سرورًا بما نالت من ثوابِ الله ورحمته، مستبشرةٌ، أي مسرورةٌ بما آتاها الله من الكرامةِ والنعيم، فرحةٌ بالبشرى؛ فجمعت بين إسفارِ الظاهرِ وضحكِ السرور «ضاحكة مستبشرة»؛ ففي هذا بيانُ تمامِ سرورِ أهلِ السعادةِ يومَ القيامة، فوجوههم مسفرةٌ ضاحكةٌ مستبشرةٌ بما نالوا من رحمةِ الله ونعيمه، جزاءَ إيمانهم وعملهم؛ فالسرورُ والاستبشارُ يومئذٍ ثمرةُ الإيمانِ والعمل؛ فاعمل أنت لتكون من الضاحكين المستبشرين يومَ القيامة، بالإيمانِ والعملِ الصالحِ والتقوى؛ فأمّا من أوتي كتابه بيمينه فيقول هاؤم اقرءوا كتابيه؛ ووجوهٌ يومئذٍ مسفرةٌ ضاحكةٌ مستبشرة؛ يستبشرون بنعمةٍ من الله وفضل؛ فالسرورُ يومَ القيامةِ لأهلِ الإيمانِ والعمل؛ فاعمل له، وآمن، واتّقِ؛ فمن آمن وعمل سُرّ، ومن كفر حزن؛ فاجعل العملَ للسرورِ والاستبشارِ دأبك."}},{"n":40,"reflection":{"text":"«ووجوه يومئذ عليها غبرة»، ووجوهُ الكفّارِ يومئذٍ عليها غبارٌ وكآبةٌ وسواد؛ ففي هذا بيانُ كآبةِ وجوهِ أهلِ الشقاءِ يومَ القيامة؛ فاحذر أن يكون وجهك من التي عليها غبرة، فكآبةُ الوجهِ يومئذٍ ثمرةُ الكفرِ والمعصية، فاتّقِ سببها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من كآبةِ الوجهِ يومَ القيامةِ باتّقاءِ الكفرِ والمعصية."},"action":{"text":"تأمّل كآبةَ الوجوه: ووجوهٌ يومئذٍ، يومَ القيامةِ، عليها غبرةٌ، أي غبارٌ وكدورةٌ وسوادٌ وكآبة، قد علاها الغمُّ والحزنُ والذلّة؛ وهي وجوهُ الكفّارِ والأشقياء «ووجوه يومئذ عليها غبرة»؛ ففي هذا بيانُ حالِ وجوهِ أهلِ الشقاءِ يومَ القيامة: غبرةٌ وكآبةٌ وسواد، جزاءَ كفرهم ومعاصيهم، مقابلَ إسفارِ وجوهِ المؤمنين؛ فكآبةُ الوجهِ يومئذٍ ثمرةُ الكفرِ والمعصية؛ فاحذر أنت أن يكون وجهك من الوجوهِ التي عليها غبرةٌ وكآبةٌ يومَ القيامة، باتّقاءِ الكفرِ والمعاصي والإقبالِ على الإيمانِ والعمل؛ ووجوهٌ يومئذٍ باسرة؛ يومَ تسودّ وجوه؛ خاشعةً أبصارهم ترهقهم ذلّة؛ فكآبةُ الوجوهِ لأهلِ الكفرِ والمعصية؛ فاتّقِ سببها، وآمن، واعمل؛ فمن آمن وعمل أشرق وجهه، ومن كفر وأساء اكتأب وجهه؛ فاجعل الحذرَ من كآبةِ الوجهِ باتّقاءِ الكفرِ دأبك."}},{"n":41,"reflection":{"text":"«ترهقها قترة»: يغشاها ويعلوها سوادٌ وظلمةٌ وذلّة؛ ففي هذا بيانُ تمامِ سوادِ وجوهِ الأشقياءِ وذلّتها؛ فاحذر سوادَ الوجهِ وذلّته يومَ القيامة، فذلّةُ الوجهِ يومئذٍ ثمرةُ الكفر، فاتّقِ سببها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من سوادِ الوجهِ وذلّته يومَ القيامة."},"action":{"text":"تأمّل غشيانَ القترة: ترهقها، أي تغشاها وتعلوها وتلحقها، قترةٌ، أي سوادٌ وظلمةٌ وغبرةٌ وذلّةٌ وكآبة؛ فتجتمع على وجوههم الغبرةُ من فوقها والقترةُ (السواد) تغشاها، فتسودّ وتظلم وتذلّ «ترهقها قترة»؛ ففي هذا بيانُ تمامِ سوادِ وجوهِ الأشقياءِ وكآبتها وذلّتها يومَ القيامة، فقد اجتمع عليها الغبرةُ والقترةُ (السواد)، جزاءَ كفرهم وفجورهم؛ فسوادُ الوجهِ وذلّته يومئذٍ ثمرةُ الكفرِ والفجور؛ فاحذر أنت سوادَ الوجهِ وذلّته وكآبته يومَ القيامة، باتّقاءِ الكفرِ والفجورِ والمعاصي؛ ويومَ القيامةِ ترى الذين كذبوا على الله وجوههم مسودّة؛ وترهقهم ذلّة؛ يومَ تسودّ وجوه؛ فسوادُ الوجوهِ وذلّتها لأهلِ الكفرِ والفجور؛ فاتّقِ سببها، وآمن، واعمل؛ فمن آمن وعمل أشرق وجهه، ومن كفر وفجر اسودّ وجهه؛ فاجعل الحذرَ من سوادِ الوجهِ باتّقاءِ الكفرِ دأبك."}},{"n":42,"reflection":{"text":"«أولئك هم الكفرة الفجرة»: أولئك أصحابُ تلك الوجوهِ هم الكفرةُ (بقلوبهم) الفجرةُ (بأعمالهم)؛ ففي هذا بيانُ أنّ سببَ سوادِ وجوههم جمعُهم الكفرَ والفجور؛ فاحذر الكفرَ والفجورَ اللذين يُسوّدان الوجهَ يومَ القيامة، فالكفرُ والفجورُ سبيلُ الشقاء، فاتّقهما بالإيمانِ والعمل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكفرِ والفجورِ اللذين يُوجِبان الشقاء."},"action":{"text":"تأمّل خاتمةَ السورة: أولئك، أي أصحابُ تلك الوجوهِ التي عليها الغبرةُ والقترة، هم الكفرةُ، أي الكافرون بالله بقلوبهم، الجاحدون لربّهم، الفجرةُ، أي الفاجرون بأعمالهم، الخارجون عن طاعةِ الله المرتكبون للمعاصي؛ فجمعوا بين كفرِ القلبِ وفجورِ العمل، فاسودّت وجوههم «أولئك هم الكفرة الفجرة»؛ ففي هذا بيانُ أنّ سببَ سوادِ وجوهِ أهلِ الشقاءِ وكآبتها جمعُهم بين الكفرِ (بالقلب) والفجورِ (بالعمل)، فكفروا بربّهم وفجروا في أعمالهم؛ فالكفرُ والفجورُ سبيلُ الشقاءِ وسوادِ الوجه؛ فاحذر أنت الكفرَ والفجورَ اللذين يُوجِبان سوادَ الوجهِ والشقاءَ يومَ القيامة، واتّقهما بالإيمانِ بالله والعملِ الصالحِ والطاعة؛ إنّ الفجّارَ لفي جحيم؛ كلّا إنّ كتابَ الفجّارِ لفي سجّين؛ الذين كفروا وصدّوا عن سبيلِ الله؛ فالكفرُ والفجورُ سبيلُ الشقاء، والإيمانُ والعملُ سبيلُ السعادة؛ فاتّقهما، وآمن، واعمل؛ فمن آمن وعمل سعد وأشرق وجهه، ومن كفر وفجر شقي واسودّ وجهه؛ فاجعل الحذرَ من الكفرِ والفجورِ والإقبالَ على الإيمانِ والعملِ دأبك."}}]}],"coverage":{"covered":42,"total":42}};
